  if (cropBox) {
    const rect = imgEl.getBoundingClientRect()
    const unzoomedWidth = (rect.width || 1) / zoom
    const unzoomedHeight = (rect.height || 1) / zoom
    const scaleX = imgEl.naturalWidth / unzoomedWidth
