### Step B: Replace Mock Data with HTTP Calls
In [office-dashboard.component.ts](file:///d:/Mazik/QHSE_Link/src/app/Pages/dashboard/office-dashboard/office-dashboard.component.ts), swap the simulated call with the actual Service Subscription:

```typescript
// 1. Inject the service in constructor
constructor(private dashboardService: DashboardService) {}

// 2. Fetch data from backend
fetchDashboardData(): void {
  this.dashboardService.getOfficeDashboard(
    this.selectedTimeline,
    this.selectedFleet,
    this.selectedVessel
  ).subscribe({
    next: (res) => {
      if (res.success) {
        this.kpis = res.data.kpis;
        this.inspectionStatus = res.data.donutStats.inspectionStatus;
        this.reportStatus = res.data.donutStats.reportStatus;
        this.inspectionCompliance = res.data.donutStats.inspectionCompliance;
        this.sailing = res.data.donutStats.sailing;
        this.chapterFindings = res.data.chapterFindings;
        this.vesselTypeFindings = res.data.vesselTypeFindings;
        this.approvedInspections = res.data.approvedInspections;
        this.pendingReviews = res.data.pendingReviews;

        this.calculateAllDonuts();
      }
    },
    error: (err) => console.error('Failed to load office dashboard', err)
  });
}
```

